class ArrayStack {
  constructor() {
    this.data = [];
  }
  push(x) {
    for (let i = this.data.length; i > 0; i--) {
      this.data[i] = this.data[i - 1];   // shift everything one place right
    }
    this.data[0] = x;                    // the top lives at index 0
  }
  pop() {
    if (this.data.length === 0) return -1;
    const x = this.data[0];
    for (let i = 0; i + 1 < this.data.length; i++) {
      this.data[i] = this.data[i + 1];   // shift everything back left
    }
    this.data.length--;
    return x;
  }
  top() {
    return this.data.length === 0 ? -1 : this.data[0];
  }
  isEmpty() {
    return this.data.length === 0;
  }
  size() {
    return this.data.length;
  }
}

