        self.data.insert(0, x)       # shifts every item right: O(n)

    def pop(self):
        if not self.data:
            return -1
        return self.data.pop(0)      # shifts every item left: O(n)

    def top(self):
        return self.data[0] if self.data else -1

    def isEmpty(self):
        return len(self.data) == 0

    def size(self):
        return len(self.data)

class ArrayStack {
    private int[] data = new int[1000];
    private int n = 0;

    void push(int x) {
        for (int i = n; i > 0; i--) data[i] = data[i - 1];   // shift right
        data[0] = x;                                          // top at index 0
        n++;
    }

    int pop() {
        if (n == 0) return -1;
        int x = data[0];
        for (int i = 0; i + 1 < n; i++) data[i] = data[i + 1];   // shift left
        n--;
        return x;
    }

    int top() {
        return n == 0 ? -1 : data[0];
    }

    boolean isEmpty() {
        return n == 0;
    }

    int size() {
        return n;
    }
}

