        if self.n == len(self.data):
            raise OverflowError("stack overflow")
        self.data[self.n] = x
        self.n += 1

    def pop(self):
        if self.n == 0:
            return -1                    # underflow
        self.n -= 1
        return self.data[self.n]

    def top(self):
        return -1 if self.n == 0 else self.data[self.n - 1]

    def isEmpty(self):
        return self.n == 0

    def size(self):
