class ArrayStack {
    private final int[] data;
    private int n = 0;                   // items in the stack; top is data[n - 1]

    ArrayStack() {
        this(1000);
    }

    ArrayStack(int capacity) {
        data = new int[capacity];
    }

    void push(int x) {
        if (n == data.length) throw new IllegalStateException("stack overflow");
        data[n++] = x;
    }

    int pop() {
        if (n == 0) return -1;           // underflow
        return data[--n];
    }

    int top() {
        return n == 0 ? -1 : data[n - 1];
    }

    boolean isEmpty() {
        return n == 0;
    }

    int size() {
        return n;
    }
}

