class ArrayStack {
    private int[] data = new int[2];     // room for 2 items to start
    private int n = 0;                   // how many items; the top is data[n - 1]

    void push(int x) {
        if (n == data.length) grow();
        data[n++] = x;
    }

    int pop() {
        if (n == 0) return -1;           // underflow
        return data[--n];
    }

    int top() {
        return n == 0 ? -1 : data[n - 1];
    }

    boolean isEmpty() {
        return n == 0;
    }

    int size() {
        return n;
    }

    private void grow() {
        int[] bigger = new int[data.length * 2];
        for (int i = 0; i < n; i++) bigger[i] = data[i];
        data = bigger;
    }
}

